import { scaledEnd, scaledPx, scaledValue } from '../../skills/scroll-animation/assets/scale'
import { reveal } from '../../skills/scroll-animation/assets/gsap/reveal'
import { scrubVideo } from '../../skills/scroll-animation/assets/gsap/scrub-video'
import { ScrollTrigger, gsap, setupGsap } from '../../skills/scroll-animation/assets/gsap/setup'

// The v2 GSAP blocks, created in page order (triggers refresh top to bottom): the reveal groups above the scene, then
// the scene.
setupGsap()
reveal(document.body)

// A tiny all-intra clip (generated by the repo root's `pretest` script into
// tests/.scratch, then copied to public/clip.mp4) -- every frame is a
// keyframe, so the scene can seek to an arbitrary frame every rAF without
// the stuck-then-jump symptom a long-GOP encode produces. Created before the
// travel section's ScrollTriggers: triggers are created in page order.
// loopSeconds: Infinity because v1's loops ran for as long as the reader
// stayed, and tests/scene-traces.mjs compares this page with that recording
// (its tail region lasts ~9 s); tests/scrub-video.mjs checks the 5 s cap.
scrubVideo(document.querySelector<HTMLElement>('[data-scene-root]')!, {
  fps: 30,
  headLoop: { fromFrame: 0, matchFrame: 5 },
  tailLoop: { fromFrame: 55 },
  loopSeconds: Infinity
})

// Scaled travel (scenes.md §12), through scale.ts: run-smoke.mjs builds this page
// with config.ts's SCALE set to FLUID_DESIGN_SCALE, so a design px is one
// --fluid. The section is 200vh tall; both tweens run from its top reaching the
// viewport top over 900 drawn px of scroll, then hold.
// tests/distance-check.mjs scrolls past the end at four viewports and asserts
// each element moved 240 * --fluid.
gsap.to('#travel-var', {
  '--scene-p': 1,
  ease: 'none',
  scrollTrigger: { trigger: '#travel', start: 'top top', end: scaledEnd(900), scrub: true, invalidateOnRefresh: true }
})
gsap.to('#travel-fn', {
  x: scaledValue(240),
  ease: 'none',
  scrollTrigger: { trigger: '#travel', start: 'top top', end: scaledEnd(900), scrub: true, invalidateOnRefresh: true }
})

// Canary: GSAP folds CSS translate into its own transform on the first
// transform tween (entrances.md §4). distance-check.mjs asserts it.
gsap.to('#fold-canary', { y: 1, duration: 0.01 })

// scaledPx's `el` param (scenes.md §12): #fluid-el-scope carries a
// literal --_fluid-m-ui, standing in for a registered mirror the fluid-design
// engine would write on a limited subtree (fluid-ui-grow-until-*). Reading
// through `el` must use that 500px/1000 = 0.5 rather than the page's own
// `ui` unit. distance-check.mjs asserts the exact value.
;(window as unknown as { __scaledPxScoped: number }).__scaledPxScoped = scaledPx(
  48,
  'ui',
  // A CHILD of the scope: the registered mirror doesn't inherit, so scaledPx
  // must walk up to #fluid-el-scope to find it.
  document.getElementById('fluid-el-child')!
)

// Exposed for tests/distance-check.mjs diagnostics.
;(window as unknown as { __ST: typeof ScrollTrigger }).__ST = ScrollTrigger
